class SpaceShip {
  #energyLevel;

  constructor(initialEnergy) {
    this.#energyLevel = initialEnergy;
  }

  charge(amount) {
    this.#energyLevel += amount;
    if (this.#energyLevel > 100) {
      this.#energyLevel = 100;
    }
    console.log(`Charging by ${amount}. Current energy: ${this.#energyLevel}`);
  }

  consumeEnergy(amount) {
    if (this.#energyLevel >= amount) {
      this.#energyLevel -= amount;
      console.log(`Consumed ${amount} energy. Remaining: ${this.#energyLevel}`);
      return true;
    } else {
      console.log(`Not enough energy to consume ${amount}. Current: ${this.#energyLevel}`);
      return false;
    }
  }

  getEnergyStatus() {
    return `Energy: ${this.#energyLevel}%`;
  }
}

